using System.IO;
using UnityEditor;
using UnityEngine;

namespace FlappyCopy.EditorTools
{
    /// <summary>
    /// Repairs assets that were generated by an editor session with an older compiled script set (Unity writes
    /// objects without the components it does not recognise) and re-applies the project settings: imports the
    /// component scripts, re-creates data, prefabs and the scene, then validates and reports.
    /// Menu "Flappy Copy/Repair Assets"; CI -executeMethod FlappyCopy.EditorTools.SceneRepair.RebuildAndExit.
    /// </summary>
    public static class SceneRepair
    {
        private static readonly string[] ComponentScripts =
        {
            "Assets/Scripts/Core/CollisionRelay.cs",
            "Assets/Scripts/Core/GameController.cs",
            "Assets/Scripts/Core/LayersBootstrapper.cs",
            "Assets/Scripts/Player/BirdController.cs",
            "Assets/Scripts/Pipes/PipePair.cs",
            "Assets/Scripts/Pipes/PipePassGate.cs",
            "Assets/Scripts/Pipes/PipeSpawner.cs",
            "Assets/Scripts/UI/HudView.cs",
            "Assets/Scripts/UI/HudController.cs",
            "Assets/Scripts/UI/PlayAreaButton.cs",
            "Assets/Scripts/UI/PortraitHudScaler.cs",
            "Assets/Scripts/UI/DeviceRect.cs",
            "Assets/Scripts/World/InfinityGround.cs",
            "Assets/Scripts/Cameras/PortraitFraming.cs"
        };

        [MenuItem("Flappy Copy/Repair Assets")]
        public static void RebuildFromMenu()
        {
            Rebuild();
        }

        public static void RebuildAndExit()
        {
            bool ok = Rebuild();
            EditorApplication.Exit(ok ? 0 : 1);
        }

        public static bool Rebuild()
        {
            foreach (string script in ComponentScripts)
            {
                if (File.Exists(script))
                {
                    AssetDatabase.ImportAsset(script, ImportAssetOptions.ForceUpdate);
                }
            }

            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
            PlayerSetup.Apply();
            GameSceneBuilder.RebuildAll();
            AssetDatabase.SaveAssets();

            var issues = ProjectValidator.Validate();
            foreach (string issue in issues)
            {
                Debug.LogError("[FlappyCopy] Repair: " + issue);
            }

            Debug.Log("[FlappyCopy] Repair finished, issues: " + issues.Count);
            return issues.Count == 0;
        }
    }
}
